{
  "findings": [
    {
      "source_id": "s0",
      "category": "assortment",
      "summary": "Компания перечисляет иммиграционные программы в нескольких странах, включая Португалию, Испанию, Францию и другие направления, а также программы гражданства.",
      "quote": "Программы Италия Visa Digital Nomad Программы Франция О жизни во Франции ВНЖ"
    },
    {
      "source_id": "s0",
      "category": "promotion",
      "summary": "Заявления о 100% одобрении и оформлении без риска отказа — рекламные обещания компании; корпус не подтверждает такие результаты.",
      "quote": "Лицензированный провайдер госпрограмм 100% одобрения заявок"
    },
    {
      "source_id": "s0",
      "category": "promotion",
      "summary": "Форма оценки собирает сведения о составе семьи, источниках дохода и сроках, затем обещает персональный расчёт и обратную связь в рабочее время.",
      "quote": "Мы уже готовим оптимальное решение на основе ваших ответов. Наберитесь немного терпения, наш менеджер свяжется с вами в течение получаса (в рабочее время)"
    },
    {
      "source_id": "s0",
      "category": "pricing",
      "summary": "Предложены два формата видеоконсультации: бесплатная 30-минутная диагностика и платная часовая консультация за €150 с планом действий и документов.",
      "quote": "Диагностика миграционного кейса (30 мин, бесплатная) Если вам необходимо понять, подойдете ли вы под текущие требования законов."
    },
    {
      "source_id": "s1",
      "category": "assortment",
      "summary": "Португальские дополнительные услуги охватывают иммиграционные и гражданские задачи, бизнес, налоги, банковские услуги и локализацию.",
      "quote": "Недвижимость и интеграция Консультации Релокационный процесс Бизнес Банковское и налоговое сопровождение ВНЖ и гражданство"
    },
    {
      "source_id": "s1",
      "category": "pricing",
      "summary": "На странице указаны отдельные цены и сроки услуг, например дистанционное открытие компании; цену следует читать с указанным условием о госпошлинах.",
      "quote": "Дистанционное открытие компании (LDA) €950,00 (гос. сборы) Выбрать Срок: 15 дней"
    },
    {
      "source_id": "s2",
      "category": "assortment",
      "summary": "В Испании заявлен широкий набор дополнительных направлений: от продления ВНЖ и гражданства до банковских, налоговых, образовательных и судебных процедур.",
      "quote": "Продление ВНЖ Гражданство и прочие виды услуг Банковские услуги Налоговые услуги Записи и взаимодействие с госорганами Испании"
    },
    {
      "source_id": "s4",
      "category": "positioning",
      "summary": "OKNO предлагает выбирать маршрут с учётом этапа переезда и текущего статуса клиента, отдельно описывая ситуации до и после въезда.",
      "quote": "Начните с того, где вы сейчас и какую задачу хотите решить. Мы поможем понять, какой следующий шаг подходит именно вам."
    },
    {
      "source_id": "s6",
      "category": "content",
      "summary": "На странице базы знаний представлены практические темы о переезде, ВНЖ, работе и бизнесе; заявлено обновление материалов при изменении правил или практики.",
      "quote": "Практические материалы о переезде, ВНЖ, работе, бизнесе и жизни в Португалии. Мы обновляем ключевые статьи, когда меняются правила или практика."
    }
  ],
  "hypotheses": [
    {
      "action": "Проверить на русскоязычной аудитории вариант входной формы, которая сначала спрашивает этап переезда, состав семьи и задачу, а затем предлагает персональный следующий шаг.",
      "evidence_indexes": [2, 6]
    },
    {
      "action": "Протестировать отдельную базу практических материалов по ключевым миграционным сценариям с датой актуализации и ссылкой на консультацию.",
      "evidence_indexes": [7]
    },
    {
      "action": "Проверить понятность прайс-листа для дополнительных услуг: показывать цену, сроки и отдельно оговаривать госпошлины или иные условия там, где они применимы.",
      "evidence_indexes": [5]
    }
  ],
  "missing_evidence": [
    "Нет данных о публикациях Immigration Relocator в социальных сетях или о фактической частоте и результатах продвижения.",
    "По конкуренту Monolite передана главная страница, но для OKNO корпус содержит отдельные страницы услуг и базы знаний; поэтому детальное сопоставление отдельных пакетов и цен неполное.",
    "Не представлены независимые подтверждения заявлений компаний об одобрениях, опыте, сроках или качестве; они рассмотрены только как заявления.",
    "Нет данных об аудитории, охвате, конверсии, фактическом чтении материалов или результатах клиентских обращений."
  ]
}
